/**
 * Invoke f (it's a forwarding call) with casts inserted as necessary.
 * 
 * @param mv
 * @param firstArgIndex
 * @param f
 */
private void generateLeafCall(MethodVisitor mv, int firstArgIndex,
        TaggedFunctionName f) {
    String sig = jvmSignatureFor(f);

    int i = firstArgIndex;
    List<Param> params = f.getParameters();
    if (f.tagF instanceof VarargsExpansion)
        params = params.subList(0, ((VarargsExpansion) f.tagF).plainCount());

    for (Param p : params) {
        mv.visitVarInsn(Opcodes.ALOAD, i);

        TypeOrPattern ty = p.getIdType().unwrap();
        if (! (ty instanceof Type))
            throw new CompilerError("Type is expected: " + ty);
        InstantiatingClassloader.generalizedCastTo(mv,  NamingCzar.jvmBoxedTypeName((Type)ty, ifNone));
        // mv.visitTypeInsn(Opcodes.CHECKCAST, NamingCzar.jvmBoxedTypeDesc((Type)ty, ifNone));
        i++;
    }
    if (CodeGenerationPhase.debugOverloading >= 3)
        System.err.println("Emitting call " + f.tagF + sig);

    if (f.tagF instanceof VarargsExpansion)
        armCallsVarargsDeclaration(mv, f, firstArgIndex);
    else
        invokeParticularMethod(mv, f, sig);
    castArmResultToRange(mv, f);
    mv.visitInsn(Opcodes.ARETURN);
}

/*
 * The branch of a varargs declaration, its plain arguments on the stack: the
 * further arguments, this dispatch method's parameters after the plain ones,
 * become the declaration's varargs array, in order, and the declaration is
 * called at its own signature (functions.tex, section "Function Applications").
 */
private void armCallsVarargsDeclaration(MethodVisitor mv, TaggedFunctionName f, int firstArgIndex) {
    VarargsExpansion ve = (VarargsExpansion) f.tagF;
    int p = ve.plainCount();
    int[] slots = new int[paramCount - p];
    for (int j = 0; j < slots.length; j++)
        slots[j] = firstArgIndex + p + j;
    CodeGen.emitVarargsArray(mv, ve.elementType(), slots, f.tagA);
    TaggedFunctionName declared = new TaggedFunctionName(f.tagA, ve.declared());
    invokeParticularMethod(mv, declared, jvmSignatureFor(declared));
}

/**
 * Where this dispatcher's declared range is one of its static parameters and the
 * arm f declares another return type, casts the arm's result to the range.  The
 * Return Type Rule makes the result a value of the range at every instance at
 * which the arm is reached; the JVM's verifier, which reads the arm's declared
 * return type, is told so.
 */
private void castArmResultToRange(MethodVisitor mv, TaggedFunctionName f) {
    if (armResultIsCastToRange(f))
        InstantiatingClassloader.generalizedCastTo(mv,
                NamingCzar.jvmBoxedTypeName(principalMember.getReturnType(), principalMember.tagA));
}

private boolean armResultIsCastToRange(TaggedFunctionName f) {
    if (principalMember == null || f == principalMember) return false;
    Type range = principalMember.getReturnType();
    Type f_return = f.getReturnType();
    if (!(range instanceof VarType) || f_return instanceof BottomType) return false;
    return !(f_return instanceof VarType
             && ((VarType) f_return).getName().getText().equals(((VarType) range).getName().getText()));
}

